using UnityEngine;
using Framework.Grid;
using Framework.Generation;
using Game.Map;

namespace Game.Tests
{
    /// <summary>
    /// MazeCellの基本動作と既存の汎用システムとの
    /// 連携を確認するテストクラス。
    /// </summary>
    public class MazeCellTest : MonoBehaviour
    {
        #region Fields

        [Header("テスト設定")]

        /// <summary>
        /// 再生開始時にテストを実行するかどうか。
        /// </summary>
        [SerializeField]
        [Tooltip("再生開始時にすべてのテストを実行する")]
        private bool runOnStart = true;

        /// <summary>
        /// 成功したテスト項目の数。
        /// </summary>
        private int passedCount;

        /// <summary>
        /// 失敗したテスト項目の数。
        /// </summary>
        private int failedCount;

        #endregion

        #region Unity Methods

        /// <summary>
        /// 再生開始時の処理。
        /// </summary>
        private void Start()
        {
            if (runOnStart)
            {
                RunAllTests();
            }
        }

        #endregion

        #region Test Management

        /// <summary>
        /// すべてのテストを実行する。
        /// </summary>
        [ContextMenu("テスト/すべてのテストを実行する")]
        public void RunAllTests()
        {
            passedCount = 0;
            failedCount = 0;

            TestTerrain();

            TestGem();

            TestItem();

            TestFlags();

            TestBreakableWall();

            TestEquality();

            TestGridMapIntegration();

            TestMazeGeneratorIntegration();

            // 最終的なテスト結果を出力する。
            string message =
                "【MazeCell テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}";

            if (failedCount == 0)
            {
                Debug.Log(
                    message + "\nすべてのテストに成功しました。",
                    this);
            }
            else
            {
                Debug.LogError(message, this);
            }
        }

        /// <summary>
        /// テスト結果を記録する。
        /// </summary>
        /// <param name="condition">テストの成功条件</param>
        /// <param name="testName">テスト項目名</param>
        private void Check(
            bool condition,
            string testName)
        {
            if (condition)
            {
                passedCount++;

                Debug.Log(
                    $"[成功] {testName}",
                    this);
            }
            else
            {
                failedCount++;

                Debug.LogError(
                    $"[失敗] {testName}",
                    this);
            }
        }

        #endregion

        #region Terrain Test

        /// <summary>
        /// 地形に応じた移動判定を確認する。
        /// </summary>
        private void TestTerrain()
        {
            // 各地形のマスを生成する。
            MazeCell floor = MazeCell.CreateFloor();

            MazeCell wall = MazeCell.CreateWall();

            MazeCell breakableWall =
                MazeCell.CreateBreakableWall();

            Check(
                floor.IsFloor && floor.IsWalkable,
                "床は移動可能");

            Check(
                wall.IsWall && !wall.IsWalkable,
                "通常の壁は移動不可能");

            Check(
                breakableWall.IsWall &&
                breakableWall.IsBreakable &&
                !breakableWall.IsWalkable,
                "破壊可能な壁の判定");
        }

        #endregion

        #region Gem Test

        /// <summary>
        /// 宝石の配置と取得を確認する。
        /// </summary>
        private void TestGem()
        {
            MazeCell cell = MazeCell.CreateFloor();

            // 宝石を配置する。
            cell = cell.PlaceGem();

            Check(
                cell.HasGem,
                "床への宝石配置");

            // 宝石を取得する。
            cell = cell.CollectGem();

            Check(
                !cell.HasGem && cell.IsFloor,
                "宝石取得後も床を維持");

            // 壁に宝石を配置しようとする。
            MazeCell wall =
                MazeCell.CreateWall().PlaceGem();

            Check(
                !wall.HasGem,
                "壁への宝石配置を防止");
        }

        #endregion

        #region Item Test

        /// <summary>
        /// アイテムの配置と取得を確認する。
        /// </summary>
        private void TestItem()
        {
            MazeCell cell = MazeCell.CreateFloor();

            cell = cell.PlaceItem();

            Check(
                cell.HasItem,
                "床へのアイテム配置");

            // アイテムが存在する場所への宝石配置を試みる。
            cell = cell.PlaceGem();

            Check(
                cell.HasItem && !cell.HasGem,
                "アイテムと宝石の重複配置を防止");

            cell = cell.CollectItem();

            Check(
                !cell.HasItem && cell.IsEmptyFloor,
                "アイテムの取得");
        }

        #endregion

        #region Flags Test

        /// <summary>
        /// 複数属性の保持と個別除去を確認する。
        /// </summary>
        private void TestFlags()
        {
            MazeCell cell = MazeCell.CreateFloor(
                MazeCellFlags.ItemSpawn);

            cell = cell.PlaceGem();

            Check(
                cell.HasGem && cell.IsItemSpawn,
                "複数属性の同時保持");

            cell = cell.CollectGem();

            Check(
                !cell.HasGem && cell.IsItemSpawn,
                "宝石取得後も配置候補を維持");

            // プレイヤーの出現地点を設定する。
            cell = cell.AddFlags(
                MazeCellFlags.PlayerSpawn);

            Check(
                cell.IsPlayerSpawn && !cell.CanPlaceGem,
                "出現地点への宝石配置を防止");

            // 地形を壁へ変更する。
            cell = cell.WithTerrain(
                MazeTerrainType.Wall);

            Check(
                cell.Flags == MazeCellFlags.None,
                "壁への変更時に属性を消去");
        }

        #endregion

        #region Wall Test

        /// <summary>
        /// 壁の破壊処理を確認する。
        /// </summary>
        private void TestBreakableWall()
        {
            MazeCell breakableWall =
                MazeCell.CreateBreakableWall();

            MazeCell destroyedWall =
                breakableWall.BreakWall();

            Check(
                destroyedWall.IsFloor &&
                destroyedWall.IsWalkable,
                "破壊可能な壁を床へ変更");

            MazeCell normalWall =
                MazeCell.CreateWall();

            Check(
                normalWall.BreakWall().IsWall,
                "通常の壁の破壊を防止");

            Check(
                breakableWall.IsBreakable,
                "変更前のマスデータを維持");
        }

        #endregion

        #region Equality Test

        /// <summary>
        /// マスデータの比較処理を確認する。
        /// </summary>
        private void TestEquality()
        {
            MazeCell first =
                MazeCell.CreateFloor().PlaceGem();

            MazeCell second =
                MazeCell.CreateFloor().PlaceGem();

            MazeCell third =
                MazeCell.CreateFloor();

            Check(
                first == second,
                "同じ内容のマスデータは等しい");

            Check(
                first != third,
                "異なる属性のマスデータを識別");
        }

        #endregion

        #region GridMap Test

        /// <summary>
        /// GridMapとの連携と変更イベントを確認する。
        /// </summary>
        private void TestGridMapIntegration()
        {
            // テスト用の床マップを生成する。
            GridMap<MazeCell> map =
                new GridMap<MazeCell>(
                    5,
                    5,
                    position => MazeCell.CreateFloor());

            // テスト対象のマス座標。
            Vector2Int testPosition =
                new Vector2Int(2, 2);

            // 変更イベントが発生した回数。
            int eventCount = 0;

            // 最後に通知された変更前後のデータ。
            MazeCell previousCell = default;
            MazeCell newCell = default;

            // マップの変更イベントを登録する。
            map.CellChanged +=
                (position, previous, current) =>
                {
                    eventCount++;

                    previousCell = previous;
                    newCell = current;
                };

            // 宝石を配置する。
            map.UpdateCell(
                testPosition,
                cell => cell.PlaceGem());

            Check(
                map.GetCell(testPosition).HasGem,
                "GridMap上への宝石配置");

            Check(
                eventCount == 1 &&
                !previousCell.HasGem &&
                newCell.HasGem,
                "宝石配置時の変更イベント");

            // 同じマスに再び宝石を配置する。
            map.UpdateCell(
                testPosition,
                cell => cell.PlaceGem());

            Check(
                eventCount == 1,
                "同一データの変更通知を抑制");

            // 宝石を取得する。
            map.UpdateCell(
                testPosition,
                cell => cell.CollectGem());

            Check(
                eventCount == 2 &&
                previousCell.HasGem &&
                !newCell.HasGem,
                "宝石取得時の変更イベント");
        }

        #endregion

        #region MazeGenerator Test

        /// <summary>
        /// 汎用迷路からゲーム専用マップへの変換を確認する。
        /// </summary>
        private void TestMazeGeneratorIntegration()
        {
            // 固定シードを使用して迷路を生成する。
            MazeGenerationSettings settings =
                new MazeGenerationSettings
                {
                    Width = 15,
                    Height = 11,
                    UseFixedSeed = true,
                    Seed = 12345
                };

            MazeGenerationResult result =
                MazeGenerator.Generate(settings);

            // ゲーム専用のマスデータへ変換する。
            GridMap<MazeCell> map =
                result.ConvertTo<MazeCell>(
                    (position, cellType) =>
                        cellType == MazeCellType.Wall
                            ? MazeCell.CreateWall()
                            : MazeCell.CreateFloor());

            Check(
                map.Width == result.Width &&
                map.Height == result.Height,
                "変換前後のマップサイズが一致");

            // 変換後の床と壁の数を取得する。
            int floorCount =
                map.CountCells(cell => cell.IsFloor);

            int wallCount =
                map.CountCells(cell => cell.IsWall);

            Check(
                floorCount == result.PassageCount,
                "変換前後の通路数が一致");

            Check(
                wallCount == result.WallCount,
                "変換前後の壁数が一致");

            // 全座標の地形が一致するか確認する。
            bool isSame = true;

            foreach (Vector2Int position
                     in map.GetPositions())
            {
                bool originalWall =
                    result.Map.GetCell(position) ==
                    MazeCellType.Wall;

                if (map.GetCell(position).IsWall
                    != originalWall)
                {
                    isSame = false;
                    break;
                }
            }

            Check(
                isSame,
                "迷路の形状を維持したデータ変換");

            Debug.Log(
                "【変換後のマップ情報】\n" +
                $"サイズ：{map.Width} × {map.Height}\n" +
                $"床数：{floorCount}\n" +
                $"壁数：{wallCount}",
                this);
        }

        #endregion
    }
}
